  'Ce que ce site contient, qui l’exploite…': ['What this site holds, who runs it…', 'Qué contiene este sitio, quién lo gestiona…', 'Was diese Website enthält, wer sie betreibt…', '该站点包含什么、由谁运营…'],
  'Site enregistré.': ['Site saved.', 'Sitio guardado.', 'Website gespeichert.', '站点已保存。'],
  'Site non enregistré': ['Site not saved', 'Sitio no guardado', 'Website nicht gespeichert', '站点未保存'],
  'Site non retiré': ['Site not removed', 'Sitio no eliminado', 'Website nicht entfernt', '站点未移除'],
  'Site retiré. Les sauvegardes déjà prises restent sur le disque.': ['Site removed. Backups already taken stay on the disk.', 'Sitio eliminado. Las copias ya hechas siguen en el disco.', 'Website entfernt. Bereits erstellte Sicherungen bleiben auf dem Laufwerk.', '站点已移除。已完成的备份仍保留在磁盘上。'],
  'Retirer ce site ?': ['Remove this site?', '¿Quitar este sitio?', 'Diese Website entfernen?', '移除此站点？'],
  'Son historique disparaît de la liste. Les sauvegardes déjà posées sur le disque restent.': ['Its history leaves the list. Backups already written to the disk stay.', 'Su historial desaparece de la lista. Las copias ya escritas en el disco se conservan.', 'Sein Verlauf verschwindet aus der Liste. Bereits geschriebene Sicherungen bleiben erhalten.', '其历史将从列表中消失。已写入磁盘的备份将保留。'],
  'Les identifiants restent sur ce serveur : ils servent à relire la base et les fichiers du site, chaque nuit.': ['Credentials stay on this server: they are what reads the site’s database and files, every night.', 'Las credenciales permanecen en este servidor: sirven para releer la base y los archivos del sitio cada noche.', 'Die Zugangsdaten bleiben auf diesem Server: Sie dienen dazu, Datenbank und Dateien der Website jede Nacht zu lesen.', '凭据保留在本服务器上：每晚用于读取站点的数据库和文件。'],
  'Jamais sauvegardé.': ['Never backed up.', 'Nunca copiado.', 'Nie gesichert.', '从未备份。'],
  'Restaurer': ['Restore', 'Restaurar', 'Wiederherstellen', '恢复'],
  'Restauration…': ['Restoring…', 'Restaurando…', 'Wird wiederhergestellt…', '正在恢复…'],
  'Restaurer ce point ?': ['Restore this backup?', '¿Restaurar esta copia?', 'Diesen Punkt wiederherstellen?', '恢复此备份点？'],
  'Le site est d’abord sauvegardé tel qu’il est — ce filet reste dans l’historique —, puis ses données sont remplacées par celles de cette sauvegarde, du {date}.':
    [
      'The site is first backed up as it is — this safety copy stays in the history — then its data is replaced with this backup from {date}.',
      'Primero se guarda el sitio tal como está — esta copia de seguridad queda en el historial — y después sus datos se sustituyen por los de esta copia del {date}.',
      'Die Website wird zuerst so gesichert, wie sie ist – diese Sicherheitskopie bleibt im Verlauf –, dann werden ihre Daten durch diese Sicherung vom {date} ersetzt.',
      '站点会先按当前状态备份（这份保险副本保留在历史中），然后其数据将被 {date} 的这份备份覆盖。',
    ],
  'Remis : {etapes}.': ['Put back: {etapes}.', 'Se restituye: {etapes}.', 'Zurückgespielt: {etapes}.', '将还原：{etapes}。'],
