  'Aucune étape : ce site ne sauvegarde rien pour l’instant.': ['No step: this site backs up nothing yet.', 'Ningún paso: este sitio aún no guarda nada.', 'Kein Schritt: Diese Website sichert noch nichts.', '没有步骤：此站点暂未备份任何内容。'],
