  'Ancien format : un dossier, sans archive zip': ['Old format: a folder, no zip archive', 'Formato antiguo: una carpeta, sin archivo zip', 'Altes Format: ein Ordner, kein ZIP-Archiv', '旧格式：一个文件夹，无 zip 压缩包'],
