  'Le point de montage du disque, chemin absolu. Vide, aucun backup ne part.': ['The disk mount point, an absolute path. Empty, no backup runs.', 'El punto de montaje del disco, ruta absoluta. Vacío, no se ejecuta ninguna copia.', 'Der Einhängepunkt des Laufwerks, absoluter Pfad. Leer, läuft kein Backup.', '磁盘挂载点，绝对路径。留空则不执行备份。'],
  'Heure du passage': ['Run time', 'Hora del pase', 'Uhrzeit des Durchlaufs', '运行时间'],
  'De 0 à 23. Après la sauvegarde du démon, pas en même temps.': ['From 0 to 23. After the daemon backup, not at the same time.', 'De 0 a 23. Después de la copia del demonio, no a la vez.', 'Von 0 bis 23. Nach der Sicherung des Daemons, nicht gleichzeitig.', '0 到 23。在守护进程备份之后，不要同时进行。'],
