  'Arrêter les {v0} agents en cours sur tous les projets ?': ['Stop the {v0} running agents across all projects?', '¿Detener los {v0} agentes en curso en todos los proyectos?', 'Die {v0} laufenden Agenten in allen Projekten stoppen?', '停止所有项目中正在运行的 {v0} 个智能体？'],
