  'Écouter le message': ['Listen to the message', 'Escuchar el mensaje', 'Nachricht anhören', '收听该消息'],
  'Extrait impossible à jouer.': ['The sample could not be played.', 'No se pudo reproducir el extracto.', 'Der Ausschnitt konnte nicht abgespielt werden.', '无法播放该片段。'],
