  'laisser vide pour en créer un sur GitHub': ['leave empty to create one on GitHub', 'dejar vacío para crear uno en GitHub', 'leer lassen, um eines auf GitHub anzulegen', '留空则在 GitHub 上新建'],
  'Démarrer un dépôt git dans le dossier': ['Start a git repository in the folder', 'Iniciar un repositorio git en la carpeta', 'Ein Git-Repository im Ordner starten', '在该目录中初始化 git 仓库'],
