  /* ---- Mode simplifié --------------------------------------------- */

  'Icône': ['Icon', 'Icono', 'Symbol', '图标'],
  "Aller rechercher l'icône du site : sur cette adresse, ou dans le dépôt du projet": [
    'Fetch the site’s icon: at this address, or in the project’s repository',
    'Buscar el icono del sitio: en esta dirección o en el repositorio del proyecto',
    'Das Symbol der Website holen: unter dieser Adresse oder im Repository des Projekts',
    '获取站点图标：从该地址，或从项目仓库中',
  ],
  '« {v0} » n\'a pas pu s\'afficher': ['“{v0}” could not be displayed', '«{v0}» no se pudo mostrar', '„{v0}“ konnte nicht angezeigt werden', '“{v0}”无法显示'],
  'En une phrase, à quoi sert ce projet ? (facultatif)': ['In one sentence, what is this project for? (optional)', 'En una frase, ¿para qué sirve este proyecto? (opcional)', 'In einem Satz: Wofür ist dieses Projekt? (optional)', '用一句话说明这个项目的用途？（可选）'],
  'Cette phrase ouvre la documentation du projet et décrit le dépôt sur GitHub.': [
    'This sentence opens the project’s documentation and describes the repository on GitHub.',
    'Esta frase abre la documentación del proyecto y describe el repositorio en GitHub.',
    'Dieser Satz eröffnet die Projektdokumentation und beschreibt das Repository auf GitHub.',
    '这句话会作为项目文档的开头，并用于描述 GitHub 上的仓库。',
  ],
  "Elle est remplie toute seule à la création du projet, et se corrige ici à la main. Elle est ouverte à la fin de chaque déploiement : si elle ne répond pas, le déploiement est déclaré en échec. Laissée vide, aucune adresse n'est contrôlée. Le bouton « Icône » relance la récupération du favicon de la colonne de gauche, sans attendre la révision automatique : sur cette adresse quand elle est remplie, et sinon dans le dépôt du projet (public/favicon.svg, favicon.ico…).": [
    'It is filled in on its own when the project is created, and corrected here by hand. It is opened at the end of every deployment: if it does not answer, the deployment is declared failed. Left empty, no address is checked. The “Icon” button restarts fetching the favicon for the left-hand column, without waiting for the automatic review: at this address when it is filled in, otherwise in the project’s repository (public/favicon.svg, favicon.ico…).',
    'Se rellena sola al crear el proyecto y se corrige aquí a mano. Se abre al final de cada despliegue: si no responde, el despliegue se declara fallido. Si se deja vacía, no se comprueba ninguna dirección. El botón «Icono» relanza la recuperación del favicon de la columna izquierda, sin esperar a la revisión automática: en esta dirección cuando está rellenada, y si no en el repositorio del proyecto (public/favicon.svg, favicon.ico…).',
    'Sie wird beim Anlegen des Projekts von selbst ausgefüllt und hier von Hand korrigiert. Sie wird am Ende jeder Bereitstellung geöffnet: Antwortet sie nicht, gilt die Bereitstellung als gescheitert. Bleibt sie leer, wird keine Adresse geprüft. Der Knopf „Symbol“ startet das Holen des Favicons für die linke Spalte neu, ohne auf die automatische Prüfung zu warten: unter dieser Adresse, wenn sie ausgefüllt ist, sonst im Repository des Projekts (public/favicon.svg, favicon.ico…).',
    '创建项目时会自动填写，也可在此手动修改。每次部署结束时都会访问该地址：若无响应，部署即判定为失败。留空则不检查任何地址。“图标”按钮会立即重新获取左栏的站点图标，无需等待自动检查：地址已填写时从该地址获取，否则从项目仓库中获取（public/favicon.svg、favicon.ico……）。',
  ],
  "Le dossier est créé pour de vrai sur le serveur, sur la branche « main », avec les fichiers d'instructions des moteurs, la mémoire, l'historique et une documentation de départ. Le projet apparaît ensuite dans la liste de gauche.": [
    'The folder is really created on the server, on the “main” branch, with the engines’ instruction files, the memory, the history and a starting documentation. The project then shows up in the left-hand list.',
    'La carpeta se crea de verdad en el servidor, en la rama «main», con los archivos de instrucciones de los motores, la memoria, el historial y una documentación inicial. El proyecto aparece luego en la lista de la izquierda.',
    'Der Ordner wird wirklich auf dem Server angelegt, im Branch „main“, mit den Anweisungsdateien der Engines, dem Gedächtnis, der Historie und einer Startdokumentation. Danach erscheint das Projekt in der linken Liste.',
    '会在服务器上真正创建目录，位于“main”分支，包含各引擎的说明文件、记忆、历史记录和一份起始文档。随后项目会出现在左侧列表中。',
  ],
  "Pour un dépôt qui n'appartient pas à ce compte. Le dépôt est récupéré sur le serveur et le projet apparaît dans la liste de gauche. Rien n'est publié ni mis en ligne au passage.": [
    'For a repository that does not belong to this account. The repository is fetched onto the server and the project shows up in the left-hand list. Nothing is published or put online in the process.',
    'Para un repositorio que no pertenece a esta cuenta. El repositorio se recupera en el servidor y el proyecto aparece en la lista de la izquierda. Nada se publica ni se pone en línea de paso.',
    'Für ein Repository, das nicht zu diesem Konto gehört. Das Repository wird auf den Server geholt und das Projekt erscheint in der linken Liste. Dabei wird nichts veröffentlicht oder online gestellt.',
    '适用于不属于该账户的仓库。仓库会被拉取到服务器上，项目随后出现在左侧列表中。过程中不会发布或上线任何内容。',
  ],
  'Tous les projets du serveur sont déjà dans votre liste.': ['Every project on the server is already in your list.', 'Todos los proyectos del servidor ya están en su lista.', 'Alle Projekte des Servers sind bereits in Ihrer Liste.', '服务器上的所有项目都已在您的列表中。'],
  '{v0} projet{v1} trouvé{v2} et pas encore suivi{v3}.': ['{v0} project{v1} found and not tracked yet{v2}{v3}.', '{v0} proyecto{v1} encontrado{v2} y aún no seguido{v3}.', '{v0} Projekt{v1} gefunden{v2} und noch nicht verfolgt{v3}.', '找到 {v0} 个尚未跟踪的项目{v1}{v2}{v3}。'],
  'Projets du serveur': ['Projects on the server', 'Proyectos del servidor', 'Projekte des Servers', '服务器上的项目'],
