  ' · pointillé : la suite au rythme observé': [' · dotted: what follows at the observed pace', ' · punteado: lo que sigue al ritmo observado', ' · gepunktet: der Verlauf im beobachteten Tempo', ' · 虚线：按观测速度的后续走势'],
  ' · pointillé : la suite, heures creuses comprises': [' · dotted: what follows, off-peak hours included', ' · punteado: lo que sigue, horas valle incluidas', ' · gepunktet: der Verlauf, Nebenzeiten inbegriffen', ' · 虚线：后续走势，含低峰时段'],
