  'fenêtre amorcée par le serveur à {v0}': ['window primed by the server at {v0}', 'ventana iniciada por el servidor a las {v0}', 'Fenster vom Server angestoßen um {v0}', '服务器于 {v0} 预热了该窗口'],
  'amorce refusée à {v0}{v1}': ['priming refused at {v0}{v1}', 'arranque rechazado a las {v0}{v1}', 'Anstoß abgelehnt um {v0}{v1}', '{v0} 的预热被拒绝{v1}'],
  'Journal des amorces': ['Priming log', 'Registro de arranques', 'Anstoß-Protokoll', '预热日志'],
  "Lancer la fenêtre de 5 h dès qu'elle repart à zéro": ['Start the 5 h window as soon as it resets', 'Lanzar la ventana de 5 h en cuanto se reinicie', 'Das 5-Stunden-Fenster starten, sobald es zurückgesetzt wird', '窗口一归零就启动 5 小时窗口'],
  "Sur Claude, la fenêtre de cinq heures ne démarre qu'au premier message. Beluga Build en envoie un minuscule dès qu'un compte revient à zéro, pour que le décompte tourne déjà quand le travail arrive.": [
    'On Claude, the five-hour window only starts at the first message. Beluga Build sends a tiny one as soon as an account resets, so the countdown is already running when the work arrives.',
    'En Claude, la ventana de cinco horas solo arranca con el primer mensaje. Beluga Build envía uno minúsculo en cuanto una cuenta vuelve a cero, para que la cuenta atrás ya corra cuando llegue el trabajo.',
    'Bei Claude startet das Fünf-Stunden-Fenster erst mit der ersten Nachricht. Beluga Build sendet eine winzige, sobald ein Konto zurückgesetzt wird, damit der Countdown schon läuft, wenn die Arbeit kommt.',
    '在 Claude 上，五小时窗口只在第一条消息时开始计时。账户一归零，Beluga Build 就发送一条极小的消息，让倒计时在工作到来前就已开始。',
  ],
  'Usage chez Cursor': ['Usage at Cursor', 'Uso en Cursor', 'Nutzung bei Cursor', 'Cursor 用量'],
  'Le forfait, la part consommée et la dépense à la demande du cycle en cours, lus chez Cursor. Les mêmes chiffres se lisent sur la carte du compte, dans le volet des quotas.': [
    'The plan, the share used and the on-demand spend for the current cycle, read from Cursor. The same figures show on the account card, in the quota panel.',
    'El plan, la parte consumida y el gasto bajo demanda del ciclo en curso, leídos en Cursor. Las mismas cifras se leen en la ficha de la cuenta, en el panel de cuotas.',
    'Tarif, verbrauchter Anteil und On-Demand-Ausgaben des laufenden Zyklus, bei Cursor gelesen. Dieselben Zahlen stehen auf der Kontokarte im Kontingentbereich.',
    '当前周期的套餐、已用比例和按需支出，均读取自 Cursor。同样的数字也显示在配额面板的账户卡片上。',
  ],
