  'Quota épuisé : ce compte ne peut plus servir avant sa remise à zéro.': ['Quota used up: this account cannot be used until it resets.', 'Cuota agotada: esta cuenta no puede usarse hasta su reinicio.', 'Kontingent aufgebraucht: dieses Konto ist bis zum Zurücksetzen nicht nutzbar.', '配额已用尽：重置前无法使用此账户。'],
