  'compte {moteur} ajouté': ['{moteur} account added', 'cuenta de {moteur} añadida', '{moteur}-Konto hinzugefügt', '{moteur} 账户已添加'],
  'outil « cursor-agent » installé{v0}': ['“cursor-agent” tool installed{v0}', 'herramienta «cursor-agent» instalada{v0}', 'Werkzeug „cursor-agent“ installiert{v0}', '已安装“cursor-agent”工具{v0}'],
  'outil « cursor-agent » absent du serveur — {v0}': ['“cursor-agent” tool missing from the server — {v0}', 'herramienta «cursor-agent» ausente del servidor — {v0}', 'Werkzeug „cursor-agent“ fehlt auf dem Server — {v0}', '服务器上缺少“cursor-agent”工具 —— {v0}'],
  'Tarif horaire': ['Hourly rate', 'Tarifa por hora', 'Stundensatz', '小时费率'],
