  'Temps de travail total': ['Total working time', 'Tiempo de trabajo total', 'Gesamte Arbeitszeit', '总工作时长'],
  'Activité au fil des jours': ['Activity day by day', 'Actividad día a día', 'Aktivität Tag für Tag', '逐日活动'],
  'Le temps de travail des agents chaque jour, tous moteurs confondus, sur le dernier mois.': [
    'The agents’ working time each day, all engines together, over the last month.',
    'El tiempo de trabajo de los agentes cada día, todos los motores juntos, durante el último mes.',
    'Die Arbeitszeit der Agenten je Tag, über alle Engines, im letzten Monat.',
    '最近一个月内，各智能体每天的工作时长（所有引擎合计）。',
  ],
  "Le total de ce que les agents ont dépensé depuis le début, projet par projet : nombre de tâches et temps de travail des agents. C'est une mesure d'usage, pas une facture — rien ici n'est facturé à personne.": [
    'The total the agents have spent since the beginning, project by project: number of tasks and agents’ working time. It is a usage measure, not an invoice — nothing here is billed to anyone.',
    'El total que han gastado los agentes desde el principio, proyecto por proyecto: número de tareas y tiempo de trabajo de los agentes. Es una medida de uso, no una factura — aquí no se factura nada a nadie.',
    'Die Gesamtsumme dessen, was die Agenten seit Beginn verbraucht haben, Projekt für Projekt: Anzahl der Aufgaben und Arbeitszeit der Agenten. Das ist eine Nutzungsmessung, keine Rechnung — hier wird niemandem etwas berechnet.',
    '自开始以来各智能体的总消耗，按项目列出：任务数量与智能体工作时长。这是用量统计，不是账单 —— 此处不向任何人计费。',
  ],
  'Touchez une barre pour voir le détail du jour.': ['Tap a bar to see that day’s detail.', 'Toque una barra para ver el detalle del día.', 'Tippen Sie auf einen Balken, um den Tag im Detail zu sehen.', '点击柱状条可查看当天明细。'],
  'Pas encore assez de relevés pour tracer la courbe.': ['Not enough readings yet to draw the curve.', 'Aún no hay suficientes lecturas para trazar la curva.', 'Noch nicht genug Messwerte, um die Kurve zu zeichnen.', '读数还不足以绘制曲线。'],
  "Les statistiques n'ont pas pu être chargées. Réessayez dans un instant.": ['The statistics could not be loaded. Try again in a moment.', 'No se pudieron cargar las estadísticas. Reinténtelo en un momento.', 'Die Statistiken konnten nicht geladen werden. Versuchen Sie es gleich erneut.', '统计数据加载失败。请稍后重试。'],
  '{v0} tâche{v1} · {v2}': ['{v0} task{v1} · {v2}', '{v0} tarea{v1} · {v2}', '{v0} Aufgabe{v1} · {v2}', '{v0} 个任务{v1} · {v2}'],
  '{v0} tâche{v1} · {v2} min': ['{v0} task{v1} · {v2} min', '{v0} tarea{v1} · {v2} min', '{v0} Aufgabe{v1} · {v2} Min.', '{v0} 个任务{v1} · {v2} 分钟'],
  '{v0} carte(s) · dernier appel {v1}': ['{v0} card(s) · last call {v1}', '{v0} tarjeta(s) · última llamada {v1}', '{v0} Karte(n) · letzter Aufruf {v1}', '{v0} 张卡片 · 最后调用 {v1}'],
  'À reconnecter dans Réglages › Comptes.': ['Reconnect it in Settings › Accounts.', 'Vuelve a conectarlo en Ajustes › Cuentas.', 'In Einstellungen › Konten neu verbinden.', '请在“设置 › 账户”中重新连接。'],
  'Chiffres anciens — {fraicheur}': ['Old figures — {fraicheur}', 'Cifras antiguas — {fraicheur}', 'Alte Zahlen — {fraicheur}', '数据较旧 —— {fraicheur}'],

