  'jamais utilisée': ['never used', 'nunca usada', 'nie benutzt', '从未使用'],
  'créée {v0}': ['created {v0}', 'creada {v0}', 'erstellt {v0}', '创建于 {v0}'],
  'révoquée {v0}': ['revoked {v0}', 'revocada {v0}', 'widerrufen {v0}', '吊销于 {v0}'],
  'modifiée {v0}': ['changed {v0}', 'modificada {v0}', 'geändert {v0}', '修改于 {v0}'],
  'Comment s\'en servir': ['How to use it', 'Cómo usarla', 'So wird er benutzt', '如何使用'],
  "Une clé permet à un service du dehors — une boîte mail, un formulaire, un automate — de poser une carte dans un projet, sans ouvrir cette application. La carte arrive dans « À planifier » et attend son lancement, comme n'importe quelle autre.": [
    'A key lets an outside service — a mailbox, a form, an automation — drop a card into a project, without opening this application. The card lands in “To plan” and waits to be started, like any other.',
    'Una clave permite que un servicio externo — un buzón, un formulario, un automatismo — deje una tarjeta en un proyecto, sin abrir esta aplicación. La tarjeta llega a «Por planificar» y espera su lanzamiento, como cualquier otra.',
    'Ein Schlüssel erlaubt einem externen Dienst — einem Postfach, einem Formular, einer Automatik —, eine Karte in ein Projekt zu legen, ohne diese Anwendung zu öffnen. Die Karte landet in „Zu planen“ und wartet auf ihren Start, wie jede andere.',
    '密钥让外部服务 —— 邮箱、表单或自动化程序 —— 无需打开本应用即可向项目投递卡片。卡片会进入“待规划”，像其他卡片一样等待启动。',
  ],
  "Le service envoie un POST à l'adresse ci-dessous, avec sa clé dans l'en-tête et, dans le corps, le projet visé (son nom suffit), un titre et une description.": [
    'The service sends a POST to the address below, with its key in the header and, in the body, the target project (its name is enough), a title and a description.',
    'El servicio envía un POST a la dirección de abajo, con su clave en la cabecera y, en el cuerpo, el proyecto destinatario (basta su nombre), un título y una descripción.',
    'Der Dienst schickt ein POST an die untenstehende Adresse, mit seinem Schlüssel im Header und im Body das Zielprojekt (der Name genügt), einen Titel und eine Beschreibung.',
    '服务向下方地址发送 POST 请求，密钥放在请求头中，请求体中包含目标项目（名称即可）、标题和描述。',
  ],
  "Le mode d'emploi complet — champs acceptés, réponses, refus — est publié à l'adresse": [
    'The full instructions — accepted fields, answers, refusals — are published at',
    'El modo de empleo completo — campos aceptados, respuestas, rechazos — se publica en la dirección',
    'Die vollständige Anleitung — akzeptierte Felder, Antworten, Ablehnungen — steht unter',
    '完整使用说明 —— 可接受的字段、响应与拒绝 —— 发布在',
  ],
  ", lisible sans compte : c'est la page à donner au service qu'on branche.": [
    ', readable without an account: that is the page to hand to the service being plugged in.',
    ', legible sin cuenta: es la página que hay que dar al servicio que se conecta.',
    ', ohne Konto lesbar: Das ist die Seite für den Dienst, den man anschließt.',
    '，无需账户即可阅读：这就是要交给所接入服务的页面。',
  ],
