  "Ce type de fichier ne s'affiche pas ici ({v0}).": ['This file type is not shown here ({v0}).', 'Este tipo de archivo no se muestra aquí ({v0}).', 'Dieser Dateityp wird hier nicht angezeigt ({v0}).', '此类文件无法在此显示（{v0}）。'],
  '{v0} fichier{v1} — {v2}': ['{v0} file{v1} — {v2}', '{v0} archivo{v1} — {v2}', '{v0} Datei{v1} — {v2}', '{v0} 个文件{v1} —— {v2}'],
  '· choisie': ['· chosen', '· elegida', '· gewählt', '· 已选'],
