  'transcription vide': ['empty transcription', 'transcripción vacía', 'leere Transkription', '空白转写'],
  'Vide = pas de silence.': ['Blank = no mute period.', 'Vacío = sin periodo de silencio.', 'Leer = keine Ruhezeit.', '留空 = 不静音。'],
  'Visuel': ['Visual', 'Visual', 'Visuell', '可视化'],

  /* ---- Télémétrie des tâches --------------------------------------- */
  'Télémétrie des tâches': ['Task telemetry', 'Telemetría de las tareas', 'Telemetrie der Aufgaben', '任务遥测'],
  'Pour chaque tâche terminée : les jetons réellement consommés par le moteur, les sujets de mémoire ouverts et le temps qu\'ils ont pris, et une estimation de qualité. Mesuré depuis la mise en service, sur les {v0} derniers jours.': ['For each finished task: the tokens actually consumed by the engine, the memory topics opened and how long they took, and a quality estimate. Measured since the feature went live, over the last {v0} days.', 'Para cada tarea terminada: los tokens realmente consumidos por el motor, los temas de memoria abiertos y el tiempo que tomaron, y una estimación de calidad. Medido desde la puesta en servicio, en los últimos {v0} días.', 'Für jede abgeschlossene Aufgabe: die tatsächlich von der Engine verbrauchten Tokens, die geöffneten Gedächtnisthemen samt ihrer Dauer und eine Qualitätsschätzung. Gemessen seit der Inbetriebnahme, über die letzten {v0} Tage.', '每个完成的任务：引擎实际消耗的词元、打开的记忆主题及其耗时，以及质量估算。自启用以来测量，涵盖最近 {v0} 天。'],
  'Tâches mesurées': ['Tasks measured', 'Tareas medidas', 'Gemessene Aufgaben', '已测量任务'],
  'sur les {v0} derniers jours': ['over the last {v0} days', 'en los últimos {v0} días', 'über die letzten {v0} Tage', '最近 {v0} 天'],
  'Jetons facturables': ['Billable tokens', 'Tokens facturables', 'Abrechenbare Tokens', '计费词元'],
  'entrée neuve et sortie, hors relecture au cache': ['fresh input and output, cache reads excluded', 'entrada nueva y salida, sin las relecturas de caché', 'neue Eingabe und Ausgabe, ohne Cache-Lesevorgänge', '新输入与输出，不含缓存重读'],
  'Durée moyenne': ['Average duration', 'Duración media', 'Durchschnittliche Dauer', '平均时长'],
  'par tâche, temps machine': ['per task, machine time', 'por tarea, tiempo de máquina', 'pro Aufgabe, Maschinenzeit', '每个任务的机器时间'],
  'Qualité moyenne': ['Average quality', 'Calidad media', 'Durchschnittliche Qualität', '平均质量'],
  'estimation, détaillée tâche par tâche': ['an estimate, detailed task by task', 'una estimación, detallada tarea por tarea', 'eine Schätzung, Aufgabe für Aufgabe aufgeschlüsselt', '估算值，逐个任务列出'],
  'Jetons et durée, jour par jour': ['Tokens against duration, day by day', 'Tokens frente a duración, día a día', 'Tokens und Dauer, Tag für Tag', '词元与时长，逐日对比'],
  'Les barres donnent les jetons du jour, la ligne la durée moyenne d\'une tâche : un jour cher n\'est pas forcément un jour long.': ['The bars give the tokens of the day, the line the average duration of a task: an expensive day is not necessarily a long one.', 'Las barras dan los tokens del día, la línea la duración media de una tarea: un día caro no es forzosamente un día largo.', 'Die Balken zeigen die Tokens des Tages, die Linie die durchschnittliche Dauer einer Aufgabe: Ein teurer Tag ist nicht zwangsläufig ein langer Tag.', '柱状表示当天的词元，折线表示任务平均时长：花费高的一天未必是漫长的一天。'],
  'Durée moyenne d\'une tâche': ['Average task duration', 'Duración media de una tarea', 'Durchschnittliche Aufgabendauer', '任务平均时长'],
  'Le détail, tâche par tâche': ['The detail, task by task', 'El detalle, tarea por tarea', 'Das Detail, Aufgabe für Aufgabe', '逐个任务的明细'],
  'Une ligne par tâche, la plus récente en tête. Ouvrez-en une pour voir d\'où vient sa note et ce qu\'elle a lu dans la mémoire du projet.': ['One row per task, the most recent first. Open one to see where its score comes from and what it read in the project memory.', 'Una fila por tarea, la más reciente primero. Abra una para ver de dónde viene su puntuación y qué leyó en la memoria del proyecto.', 'Eine Zeile pro Aufgabe, die neueste zuerst. Öffnen Sie eine, um zu sehen, woher ihre Bewertung kommt und was sie im Projektgedächtnis gelesen hat.', '每个任务一行，最新的排在最前。展开某一行可查看评分来源及其读取的项目记忆。'],
  'La note compare chaque tâche à la médiane mesurée sur ce dépôt : {v0} jetons et {v1} min. C\'est une estimation du déroulé, pas un jugement du code produit.': ['The score compares each task with the median measured on this repository: {v0} tokens and {v1} min. It estimates how the task went, it does not judge the code produced.', 'La puntuación compara cada tarea con la mediana medida en este repositorio: {v0} tokens y {v1} min. Estima cómo transcurrió la tarea, no juzga el código producido.', 'Die Bewertung vergleicht jede Aufgabe mit dem in diesem Repository gemessenen Median: {v0} Tokens und {v1} Min. Sie schätzt den Ablauf ein, sie beurteilt nicht den erzeugten Code.', '评分将每个任务与本仓库测得的中位数比较：{v0} 个词元与 {v1} 分钟。它评估的是执行过程，而非产出的代码。'],
  'Aucune tâche mesurée pour l\'instant. Ce bloc se remplit à la fin de chaque tâche lancée depuis la mise en service de la mesure.': ['No task measured yet. This block fills up at the end of every task started since the measurement went live.', 'Ninguna tarea medida por ahora. Este bloque se llena al final de cada tarea lanzada desde la puesta en servicio de la medición.', 'Noch keine Aufgabe gemessen. Dieser Block füllt sich am Ende jeder Aufgabe, die seit der Inbetriebnahme der Messung gestartet wurde.', '目前尚无已测量的任务。自测量启用以来，每个任务结束时都会填充此区块。'],
  'Aucune tâche mesurée sur la période.': ['No task measured over the period.', 'Ninguna tarea medida en el periodo.', 'Keine Aufgabe im Zeitraum gemessen.', '该时段没有已测量的任务。'],
  '{v0} min par tâche': ['{v0} min per task', '{v0} min por tarea', '{v0} Min. pro Aufgabe', '每个任务 {v0} 分钟'],
  'mémoire triée à {v0}': ['memory filtered by {v0}', 'memoria filtrada al {v0}', 'Gedächtnis zu {v0} gefiltert', '记忆筛除 {v0}'],
  '{v0} min': ['{v0} min', '{v0} min', '{v0} Min.', '{v0} 分钟'],
  '{v0} tâche{v1}': ['{v0} task{v1}', '{v0} tarea{v1}', '{v0} Aufgabe{v1}', '{v0} 个任务{v1}'],
  '{v0} tour{v1}': ['{v0} turn{v1}', '{v0} turno{v1}', '{v0} Durchgang{v1}', '{v0} 轮{v1}'],
