  'Backups du projet': ['Project backups', 'Copias del proyecto', 'Projekt-Backups', '项目备份'],
  'Les backups n’ont pas pu être lus.': ['The backups could not be read.', 'No se pudieron leer las copias.', 'Die Backups konnten nicht gelesen werden.', '无法读取备份。'],
  'Le téléchargement n’a pas pu démarrer.': ['The download could not start.', 'No se pudo iniciar la descarga.', 'Der Download konnte nicht starten.', '无法开始下载。'],
  'Chaque archive est une copie de votre projet prise sur le serveur. Téléchargez celle dont vous avez besoin : rien n’est remis en place depuis ici.': [
    'Each archive is a copy of your project taken on the server. Download the one you need: nothing is restored from here.',
    'Cada archivo es una copia de su proyecto tomada en el servidor. Descargue la que necesite: nada se restaura desde aquí.',
    'Jedes Archiv ist eine Kopie Ihres Projekts, auf dem Server erstellt. Laden Sie das benötigte herunter: Von hier aus wird nichts wiederhergestellt.',
    '每个归档都是在服务器上生成的项目副本。请下载您需要的那一份：此处不会进行任何恢复。',
  ],
  'Aucune archive disponible pour ce projet pour l’instant.': ['No archive available for this project yet.', 'Todavía no hay ningún archivo disponible para este proyecto.', 'Für dieses Projekt ist noch kein Archiv verfügbar.', '该项目暂时没有可用的归档。'],
