  'L’espace « Accès » n’a pas pu être lu.': ['The “Access” space could not be read.', 'No se pudo leer el espacio «Acceso».', 'Der Bereich „Zugang“ konnte nicht gelesen werden.', '无法读取“访问”空间。'],
  'Le geste n’a pas pu aboutir.': ['The action could not be completed.', 'La acción no pudo completarse.', 'Die Aktion konnte nicht abgeschlossen werden.', '操作未能完成。'],
