  'Les personnes qui ont le plus besoin du produit, décrites précisément.': ['The people who need the product most, described precisely.', 'Las personas que más necesitan el producto, descritas con precisión.', 'Die Menschen, die das Produkt am meisten brauchen, genau beschrieben.', '最需要这个产品的人，要描述得具体。'],
