  'Sa promesse': ['Its promise', 'Su promesa', 'Sein Versprechen', '它的承诺'],
  'Ce que le produit change pour elles, en une phrase.': ['What the product changes for them, in one sentence.', 'Lo que el producto cambia para ellas, en una frase.', 'Was das Produkt für sie ändert, in einem Satz.', '用一句话说明产品为他们带来的改变。'],
